import{_ as t,o,a as n,d as r}from"./chunks/framework.IehvnstE.js";const f=JSON.parse('{"title":"Stuzhik Connect","description":"Stuzhik Connect — direct P2P transfer of modpacks and builds between friends, with no servers. Friends list, connection codes, VPN, security.","frontmatter":{"description":"Stuzhik Connect — direct P2P transfer of modpacks and builds between friends, with no servers. Friends list, connection codes, VPN, security.","head":[["meta",{"name":"keywords","content":"stuzhik connect, send modpack to friend, share minecraft modpack, p2p minecraft, share minecraft builds, minecraft without server"}]]},"headers":[],"relativePath":"en/guide/connect.md","filePath":"en/guide/connect.md"}'),i={name:"en/guide/connect.md"};function a(s,e,d,l,h,c){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h1><p>Take a build or a modpack from a friend directly, with no cloud and no server of ours: the files go from their computer to yours.</p><div class="warning custom-block"><p class="custom-block-title">Works within one network</p><p>Stuzhik finds devices on the same network: a home or local one, or a virtual one set up by a VPN app. Stuzhik has no server of its own for connecting over the internet, and if you and your friend are on different networks (different homes, cities, ISPs), your home routers will almost always block a direct connection between you.</p><p>Same Wi-Fi or LAN: it just works. Different networks: you need a shared VPN, <a href="#if-you-are-on-different-networks">see below</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Version 0.0.19 or newer, for both of you</p><p>Since 0.0.19 Connect uses a new protocol (Connect 2), and launchers 0.0.18 and older can&#39;t connect to it at all: both of you need to update. If there is a Stuzhik of another version nearby, the connection status panel in the «Friends» section says so.</p></div><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><ol><li>Open «Friends» in the sidebar</li><li>Click «Turn on»</li><li>The first time, the launcher asks who can see you. By default nobody: Connect is on, but you don&#39;t exist for the network until you choose «Friends only» or «Everyone» (<a href="#visibility">Visibility</a>)</li><li>Your code: <code>STUZHIK-XXXXXX</code>, 6 characters after the prefix. The «Invite» button copies it</li></ol><h2 id="connecting-to-a-friend" tabindex="-1">Connecting to a friend <a class="header-anchor" href="#connecting-to-a-friend" aria-label="Permalink to &quot;Connecting to a friend&quot;">​</a></h2><h3 id="auto-discovery" tabindex="-1">Auto-discovery <a class="header-anchor" href="#auto-discovery" aria-label="Permalink to &quot;Auto-discovery&quot;">​</a></h3><p>On the same network Stuzhik <strong>finds devices by itself</strong>: there is nothing to type, your friend shows up in the «People» list. They just must not be «Invisible».</p><h3 id="by-code" tabindex="-1">By code <a class="header-anchor" href="#by-code" aria-label="Permalink to &quot;By code&quot;">​</a></h3><ol><li>Ask your friend for their code</li><li>Click «Add device» and paste the code</li><li>Confirm with the «Add device» button</li></ol><p>The code looks for your friend through the same network broadcast as auto-discovery: it is there to reach exactly the right person when the list has many devices. That is why the code also works <strong>only on the same network</strong> (real or VPN) and only if your friend is not «Invisible».</p><p>Old-format codes (4 characters) are no longer accepted: your friend&#39;s code updates by itself once they update the launcher.</p><h3 id="by-address" tabindex="-1">By address <a class="header-anchor" href="#by-address" aria-label="Permalink to &quot;By address&quot;">​</a></h3><p>The device is not found by itself (say, you are on Tailscale): «Add device» and your friend&#39;s address, <code>100.64.0.5</code> or <code>100.64.0.5:19848</code>. The port can be left out, the standard 19848 is used: you need it only if your friend&#39;s Connect took a fallback port.</p><h2 id="friends" tabindex="-1">Friends <a class="header-anchor" href="#friends" aria-label="Permalink to &quot;Friends&quot;">​</a></h2><p>A device you found is not a friend yet. To add one:</p><ol><li>«⋯» next to the person (or right-click them) → «Add friend». After adding by code or address, the launcher offers this by itself</li><li>Your friend accepts the request on their side: it arrives in «Inbox» (the bell) and in the «People» list</li><li>Done: the launcher recognizes your friend by a signature made with their key, and nobody can pretend to be them</li></ol><p>The launcher remembers friends with their addresses, up to eight per friend: local network, VPN, internet. When Connect turns on, it reaches out at every remembered address at once, so <strong>a friend is found even where auto-discovery does not work</strong>, and after one of you has left the shared local network (<a href="#tailscale-and-other-networks-without-broadcast">Tailscale</a>).</p><h3 id="check-connection" tabindex="-1">Check connection <a class="header-anchor" href="#check-connection" aria-label="Permalink to &quot;Check connection&quot;">​</a></h3><p>«Check connection» in a person&#39;s card does a real handshake, the same one as before a build transfer, at every known address at once, and <strong>shows the result for each address</strong>: «answers, N ms», «no answer», «different Stuzhik version» or «you are hidden from them». Next to the address you see what kind of network it is: local network, Tailscale, Radmin VPN, Hamachi or internet.</p><p>A friend can be checked even when they are «offline»: if a remembered address comes back to life, the friend shows up in the list right away.</p><p>A server a friend opened or is playing on shows in their room: latency, how many players are online, the version and the server message. «Join» installs the server&#39;s build and connects you to it: <a href="/en/guide/servers.html#friends-servers">Friends&#39; servers</a>.</p><h2 id="visibility" tabindex="-1">Visibility <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;Visibility&quot;">​</a></h2><p>You choose the mode in Connect settings:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Who sees you</th></tr></thead><tbody><tr><td>Invisible</td><td><strong>Nobody.</strong> The device does not go on the network at all: it answers no one and announces nothing about itself. Friends won&#39;t find you, only you can find them</td></tr><tr><td>Friends only</td><td><strong>Only friends see your nickname, builds and what you are playing.</strong> The device itself is noticeable on the network to everyone (otherwise friends couldn&#39;t find you), but only a friend can tell it is you: the identifying marker changes every 10 minutes and means nothing to outsiders</td></tr><tr><td>Everyone</td><td><strong>Any Stuzhik user on this network</strong> sees you in the list, with your nickname if showing it is on</td></tr></tbody></table><p>You can also hide from one friend: «Hide from this friend» in their menu. To them you are «Invisible», everyone else sees you as usual.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Your own card: «My profile» → «Customize», the «Appearance» tab. Others see it <strong>exactly as you see it yourself</strong>:</p><ul><li><strong>Banner</strong>: a live effect in the header or across the whole card, and «Banner color»</li><li><strong>Avatar</strong>: the picture is cropped to a 256×256 square. «Behind the picture»: «Default», a color of your choice or «Transparent» (for PNG and WebP with a transparent background)</li><li><strong>Frames</strong>: separately for the avatar and the whole card (line, double, glow, gradient and animated ones). «Frame color»: the accent or your own</li><li><strong>Accent</strong> and the «About you» line</li></ul><p>A color can be picked on the square, with an eyedropper from the screen, or pasted as text: <code>#4f8cff</code>, <code>rgb(79 140 255)</code>, <code>hsl(…)</code> or just a color name.</p><p>Who sees the appearance is set by «Who sees my profile style» in Connect settings: «Everyone who can see me» or «Friends only». Nickname and online visibility are set separately.</p><h2 id="transfer" tabindex="-1">Transferring modpacks <a class="header-anchor" href="#transfer" aria-label="Permalink to &quot;Transferring modpacks {#transfer}&quot;">​</a></h2><p>You can&#39;t send a build to a friend: <strong>Connect only works by pulling</strong>. Your friend takes the build, and your launcher asks you for permission, and the question says plainly what your friend wants to get.</p><h3 id="opening-a-build-to-friends" tabindex="-1">Opening a build to friends <a class="header-anchor" href="#opening-a-build-to-friends" aria-label="Permalink to &quot;Opening a build to friends&quot;">​</a></h3><p><strong>By default builds are not published</strong>, they don&#39;t exist for the network. To open one: right-click the build (or «⋯») → «Sharing» → «Friends only» or «Everyone on the network». For your friends to have something to choose from, «Show modpack list» must be on in Connect settings.</p><p>Who can ask for a build and whether you are asked every time is also set in Connect settings. <strong>By default only friends can ask, and every transfer happens only with your consent.</strong></p><h3 id="getting-a-build-from-a-friend" tabindex="-1">Getting a build from a friend <a class="header-anchor" href="#getting-a-build-from-a-friend" aria-label="Permalink to &quot;Getting a build from a friend&quot;">​</a></h3><ol><li>Your friend&#39;s card → «Modpacks» → «Refresh» to get the list</li><li>«Get» next to the build you want. Or «Get modpack…» in your friend&#39;s menu: there you first see what will be downloaded and what you already have</li><li>Your friend gets the question «Transfer request: … wants to receive from you …». <strong>The files move only once they click «Allow»</strong></li></ol><p>The question does not disappear on a timer: it waits for an answer while the person asking is connected. One «Allow» covers the whole transfer, so if the connection drops, resuming won&#39;t ask again. «Remember for this user» remembers the answer for this friend and this build.</p><h3 id="during-a-transfer" tabindex="-1">During a transfer <a class="header-anchor" href="#during-a-transfer" aria-label="Permalink to &quot;During a transfer&quot;">​</a></h3><ul><li><strong>Progress</strong> in the transfers block of the «Friends» section, the full list in «All transfers»</li><li><strong>Cancel</strong> there too, and whoever is getting the build can also pause and resume</li><li><strong>Only the difference</strong>: missing and changed files are transferred</li><li><strong>A dropped connection</strong> is fine: the transfer continues from where it stopped</li><li><strong>Checked</strong>: every downloaded file is verified against its hash before it goes into the build</li></ul><h2 id="coop-build" tabindex="-1">Co-op build <a class="header-anchor" href="#coop-build" aria-label="Permalink to &quot;Co-op build {#coop-build}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Experimental feature</p><p>Turned on in Settings → Experiments → «Experimental features». While it is off, it is nowhere in the interface.</p></div><p>A build can be put together with friends: the host opens a room, friends join, propose and discuss mods, and edit configs.</p><h3 id="opening-a-room" tabindex="-1">Opening a room <a class="header-anchor" href="#opening-a-room" aria-label="Permalink to &quot;Opening a room&quot;">​</a></h3><p>«Friends» → «Build together» → one of your builds, «New build» (from scratch, friends add the mods themselves) or a project from the <a href="/en/guide/builder.html">Builder</a>. The same window has «Who can join»:</p><ul><li><strong>«Friends»</strong>: the default, confirmed friends only</li><li><strong>«Anyone who sees me»</strong>: strangers can only watch</li><li><strong>«By invitation»</strong>: only those ticked in the room settings</li></ul><h3 id="in-the-room" tabindex="-1">In the room <a class="header-anchor" href="#in-the-room" aria-label="Permalink to &quot;In the room&quot;">​</a></h3><ul><li><strong>Roles.</strong> An «Editor» changes the contents directly, a «Member» puts changes to a vote, a «Viewer» watches and discusses. A stranger is always a viewer. The host sets roles and permissions (view and edit configs, vote, take the build without asking, copy the room) in the room settings</li><li><strong>Build editor.</strong> «Open the build editor»: the tabs «Build», «Catalog», «Compatibility», «Configs». Only the host installs mods: a member&#39;s edit is a proposal, and the host&#39;s launcher takes the files from Modrinth and CurseForge</li><li><strong>Compatibility.</strong> «By composition» and «Dependency graph» are open to everyone in the room, no need to install the build for that</li><li><strong>Proposals and discussion.</strong> Votes, the «Pack edits» feed (a change to the contents can be undone) and «Discussion», the room&#39;s shared chat</li></ul><h3 id="your-own-copy" tabindex="-1">Your own copy <a class="header-anchor" href="#your-own-copy" aria-label="Permalink to &quot;Your own copy&quot;">​</a></h3><p>«Get the pack» installs a copy of the host&#39;s build for you, and «Update my copy automatically» keeps up with the host&#39;s changes. A room of your own based on someone else&#39;s («My own room based on this one») is possible only if the host gave the «Copy the room» permission: by default nobody has it.</p><p>When the host goes offline, the room closes. A pinned room («Pin the room») comes back by itself when the host reappears.</p><h2 id="if-you-are-on-different-networks" tabindex="-1">If you are on different networks <a class="header-anchor" href="#if-you-are-on-different-networks" aria-label="Permalink to &quot;If you are on different networks&quot;">​</a></h2><p>Home routers and mobile internet almost always block a direct connection between different networks. That is how NAT works: it is not a Stuzhik bug, and not something we can get around on our own. What works is <strong>a shared virtual network</strong> over the internet. You both install the same VPN app, it puts your devices on one network, and Connect works on it.</p><p>We don&#39;t develop or support these apps, this is just a recommendation of what works. Stuzhik is not affiliated with these services and does not distribute them: only the names are given here, find the official website with a search engine.</p><table tabindex="0"><thead><tr><th>Option</th><th>Difficulty</th><th>How friends are found</th></tr></thead><tbody><tr><td>Radmin VPN</td><td>Easy</td><td>By themselves, like on a regular LAN</td></tr><tr><td>ZeroTier</td><td>Medium</td><td>By themselves, when you are both in the same ZeroTier network</td></tr><tr><td>Tailscale</td><td>Hard</td><td>By address once, by themselves after that (<a href="#tailscale-and-other-networks-without-broadcast">see below</a>)</td></tr></tbody></table><p>Hamachi also puts devices on a shared network, and discovery works in it by itself. Tips on these options are in the launcher too, in the «Friends» section (also without links, names only).</p><p><strong>Through Steam.</strong> If you both have Steam, you can also play through it (an experimental feature, turned on in «Settings → Steam»): open the world to the network, and your friends get «Join» in their Steam friends list. Their launcher picks or installs the same build and connects them to you through the Steam network, with no open ports. Friends see you in the game «Spacewar»: that is the name of the Steam test app it runs through.</p><h3 id="tailscale-and-other-networks-without-broadcast" tabindex="-1">Tailscale and other networks without broadcast <a class="header-anchor" href="#tailscale-and-other-networks-without-broadcast" aria-label="Permalink to &quot;Tailscale and other networks without broadcast&quot;">​</a></h3><p>Tailscale and other IP-level tunnels don&#39;t carry broadcast packets, so auto-discovery and the code find nobody in them. You add your friend <strong>by address, but only once</strong>:</p><ol><li>Ask your friend for their Tailscale address, it looks like <code>100.x.y.z</code></li><li>«Add device» → that address. The port can be left out: 19848 by default</li><li>Add them as a friend, your friend accepts the request</li></ol><p><strong>After that, it all happens by itself.</strong> After the first handshake in which your friend proved who they are with their signature, the launcher remembers their address. When Connect turns on, and then every 5 minutes, it reaches out to the remembered address, and once it gets through, keeps your friend online while they answer. A friend who got through to you on their own also shows up in the list. Co-op build rooms, profile style and «playing …» reach such a friend the same way as over a local network.</p><p>Only confirmed friends are remembered. In «Invisible» mode the launcher reaches out to nobody, and never to a friend you are hidden from.</p><h2 id="firewall" tabindex="-1">Firewall <a class="header-anchor" href="#firewall" aria-label="Permalink to &quot;Firewall&quot;">​</a></h2><p>Connect works <strong>over UDP only</strong>: discovery on port 19847, connections on 19848. If a port is taken by another program, Connect takes a fallback one (+10, +20 or +30).</p><p>On Windows both ports need one firewall rule, «Stuzhik Connect». The «Add firewall rule» button in the «Friends» section adds it (Windows asks for permission). The rule from versions before 0.0.19 opened transfers over TCP and no longer helps: the connection screen notices it and offers to set the rule up again. Press «Add firewall rule» once more, and the new one replaces the old one.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li><strong>Everything is encrypted.</strong> Connections run over QUIC with TLS 1.3 and are encrypted entirely: the files, every message and the handshake itself. Key exchange is a hybrid of X25519 and ML-KEM-768, the keys are new for every connection</li><li><strong>A friend can&#39;t be faked.</strong> The launcher recognizes them by a key signature bound to this connection: an overheard signature can&#39;t be presented in another connection</li><li><strong>An observer on the same network</strong> sees that a connection exists, its size and that it is Stuzhik, but not its contents</li><li><strong>Nothing is taken without asking.</strong> Files leave only after you click «Allow». That is the default: in the «Sharing modpacks» settings, «Ask for permission» can be switched to «Except friends» or «Never»</li><li><strong>Executable files</strong> (<code>.exe</code>, <code>.bat</code>, <code>.ps1</code>, <code>.sh</code>, etc.) are never transferred, not even with a <code>.disabled</code> suffix</li><li><strong>A blocked user</strong> can&#39;t send requests and is not visible in the list</li><li><strong>Your public IP is not sent.</strong> When you meet, a friend gets only your home network and VPN addresses (Radmin, Tailscale, Hamachi), even if the computer is connected to the internet directly, without a router</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="my-friend-can-t-be-found-on-the-network" tabindex="-1">My friend can&#39;t be found on the network <a class="header-anchor" href="#my-friend-can-t-be-found-on-the-network" aria-label="Permalink to &quot;My friend can&#39;t be found on the network&quot;">​</a></h3><ol><li>Have you both turned on Connect, and are you both on 0.0.19 or newer?</li><li>Is your friend not «Invisible»? In that mode there is no way to find them</li><li>Are you really on the same network, physical or through a shared VPN? The VPN app must be <strong>connected on both sides</strong>, not just installed</li><li>Auto-discovery does not work in Tailscale: add your friend by address (<a href="#tailscale-and-other-networks-without-broadcast">see above</a>)</li><li>Firewall: «Add firewall rule» in the «Friends» section</li><li>If you are already friends, «Check connection» in their card shows what exactly is wrong</li></ol><h3 id="a-transfer-is-stuck" tabindex="-1">A transfer is stuck <a class="header-anchor" href="#a-transfer-is-stuck" aria-label="Permalink to &quot;A transfer is stuck&quot;">​</a></h3><ol><li>Look at the transfers in the «Friends» section: it may be paused</li><li>Resume it by hand</li><li>Still stuck: cancel it and get the build again. Only missing and changed files are transferred</li></ol><h3 id="a-friend-request-doesn-t-arrive" tabindex="-1">A friend request doesn&#39;t arrive <a class="header-anchor" href="#a-friend-request-doesn-t-arrive" aria-label="Permalink to &quot;A friend request doesn&#39;t arrive&quot;">​</a></h3><ul><li>Your friend may have «Accept friend requests» off in Connect settings: then requests are dropped silently, and the sender never finds out</li><li>Your friend is «Invisible»: they can&#39;t be seen, so there is nowhere to send the request</li><li>In «Friends only» mode strangers see you without a nickname, as «Anonymous». To make sure your friend finds exactly you, give them your code</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/en/guide/modpacks.html">Modpacks</a></li><li><a href="/en/guide/collections.html">Mod Collections</a></li><li><a href="/en/faq.html">FAQ</a></li></ul>',78)])])}const y=t(i,[["render",a]]);export{f as __pageData,y as default};
